from pathlib import Path
import json,html,shutil,hashlib,subprocess
import argparse
parser=argparse.ArgumentParser();parser.add_argument('--render-directory',required=True);args=parser.parse_args()
r=Path(__file__).resolve().parents[1]
src=Path(args.render_directory)
out=r/'web/downloads/blueprintbench/presentation';out.mkdir(parents=True,exist_ok=True)
slides=json.loads((src/'public-slides.json').read_text())
assert len(slides)==15
figures=[];toc=[];manifest=[]
for i,row in enumerate(slides,1):
 name=f'slide-{i}.jpg';png=src/f'slide-{i}.png';assert png.exists(),png
 subprocess.run(['sips','-s','format','jpeg','-s','formatOptions','88',str(png),'--out',str(out/name)],check=True,stdout=subprocess.DEVNULL)
 title=row['title'];text=row['text'];toc.append(f'<a href="#slide-{i}">{i:02d}. {html.escape(title)}</a>')
 transcript=''.join('<p>'+html.escape(t).replace('\n','<br>')+'</p>' for t in text if t.strip())
 figures.append(f'<figure id="slide-{i}" tabindex="-1"><img src="{name}" alt="Slide {i}: {html.escape(title)}" width="1280" height="720" loading="{ "eager" if i==1 else "lazy"}"><figcaption><h2>{i:02d}. {html.escape(title)}</h2><details><summary>Read the slide transcript</summary>{transcript}</details></figcaption></figure>')
 manifest.append({'slide':i,'file':name,'title':title,'original_url':'https://raw.githubusercontent.com/sev7enITA/PALO-BlueprintBench/f14680e7f826607c4e78c2d537df446125d7aed3/web/downloads/blueprintbench/presentation/'+name,'sha256':hashlib.sha256((out/name).read_bytes()).hexdigest()})
(out/'slides.json').write_text(json.dumps({'edition':'2026-11-11','qualification':'Internal testing, independent qualification pending','source_commit':'f14680e7f826607c4e78c2d537df446125d7aed3','hash_scope':'Checksums identify original uploaded bytes; the image delivery service may optimise copies.','slides':manifest},indent=2)+'\n')
(out/'index.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'none'; style-src 'self' 'unsafe-inline'; img-src 'self'; object-src 'none'; base-uri 'none'"><title>BlueprintBench: specification fidelity and internal testing</title><meta name="description" content="A fifteen-slide introduction to PALO BlueprintBench, real application captures and the 18-model internal procurement cohort. Independent validation pending."><link rel="canonical" href="https://paloframework.org/downloads/blueprintbench/presentation/index.html"><style>
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#091320;color:#edf5fa;font:17px/1.6 system-ui,sans-serif}a{color:#5ee9d7}header,main,footer{max-width:1280px;margin:auto;padding:22px}header img{width:300px;max-width:70%;height:auto}h1{font-size:clamp(28px,4vw,48px);line-height:1.15}h2{font-size:23px}nav{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:6px 20px;margin:24px 0}figure{margin:0 0 42px;scroll-margin-top:16px;border-bottom:1px solid #294252}figure img{display:block;width:100%;height:auto}figcaption{padding:10px 10px 24px}summary{cursor:pointer;color:#5ee9d7}details p{max-width:90ch;color:#b7c8d8}.status{color:#b7c8d8}.links{display:flex;flex-wrap:wrap;gap:20px}.top{position:fixed;right:16px;bottom:16px;padding:8px 14px;background:#132436;border:1px solid #5ee9d7;border-radius:4px}@media print{header nav,.links,.top,details,footer{display:none}header{page-break-after:always}figure{page-break-after:always;border:0;margin:0}figcaption{display:none}main{padding:0}}</style></head><body><header id="top"><img src="../../../assets/blueprintbench/brand/blueprintbench-logo.jpg" alt="PALO BlueprintBench"><h1>Specification fidelity and internal testing</h1><p class="status">15 slides. Updated 11 November 2026. Actual application and leaderboard captures. Independent qualification pending.</p><div class="links"><a href="../../../PALO_BlueprintBench.html">Research overview</a><a href="../../../PALO_BlueprintBench_Leaderboard.html">Leaderboard</a><a href="https://chatgpt.com/space/page_4a816fc3283c8191ba4609dafd42d79f">Editable presentation (access required)</a><a href="../brand-kit.zip">Brand kit</a></div><nav aria-label="Slide index">'''+''.join(toc)+'''</nav></header><main>'''+''.join(figures)+'''</main><footer><p>PALO Framework / Fabrizio Degni. Internal results use assistant-draft labels on three short synthetic procurement cases from one authored family. No PALO Blueprint Index or independent certification.</p><p>The image service may optimise delivery copies. The slide manifest links to the original files in Git and records their checksums.</p><a href="slides.json">Original-image manifest</a> · <a href="../internal-cohort-report.md">Evidence report</a></footer><a class="top" href="#top" aria-label="Back to slide index">Slide index ↑</a></body></html>''')
print(json.dumps({'slides':len(slides),'viewer':str(out/'index.html')}))
